import {analyze} from './detector.mjs?v=20261114-10';
import {CASE_BANK,drawRound,scoreAnswer} from './cases.mjs?v=20261114-10';
const $=s=>document.querySelector(s);
const node=(tag,text='',cls='')=>{const n=document.createElement(tag);n.textContent=text;if(cls)n.className=cls;return n;};
const evidence=(id,title,quote,why)=>({id,title,quotes:[quote],why});
const usedCases=new Set();
let cases=drawRound(usedCases);
let aiGeneration=0,gmailSelectedText=false;
let liveRoom=null, liveState=null, pollHandle=null, liveOffset=0, liveBusy=false;
let timed=false,deadline=0,frozenRemaining=20000,points=0,awarded=new Map();
let current=0, mode='training', pinned=new Map(),answers=new Map(),revealed=false,customText='';
const list=$('#case-list');
function updateList(){list.replaceChildren();cases.forEach((c,i)=>{const b=node('button','','case-row'+(mode==='training'&&i===current?' active':'')+(answers.has(i)?' solved':''));b.setAttribute('aria-label',`Case ${i+1}: ${c.title}${answers.has(i)?', reviewed':''}`);if(mode==='training'&&i===current)b.setAttribute('aria-current','true');const text=node('span');text.append(node('span',c.title,'case-row-title'),node('span',c.subtitle,'case-row-subtitle'),node('span',answers.has(i)?'FILE REVIEWED':'CASE FILE / '+String(i+1).padStart(3,'0'),'case-row-tag'));b.append(node('span',String(i+1).padStart(2,'0'),'case-num'),text,node('span','','row-dot'));b.addEventListener('click',()=>{if(!liveRoom&&!timed)openCase(i);});if(liveRoom||timed)b.disabled=true;list.append(b);});$('#case-counter').textContent=`${answers.size} / ${cases.length} FILED`;const correct=[...answers.values()].filter(Boolean).length;$('#detective-rank').textContent=answers.size===cases.length?(correct===cases.length?'Chief of trust issues':correct>=3?'Sharp-eyed investigator':'Detective in training'):'Unlicensed detective';$('#detective-score').textContent=answers.size?`${correct} correct · ${answers.size} file${answers.size===1?'':'s'} reviewed`:'80 cases. Ten fresh rounds.';}
function setPanel(panel){if(panel==='inbox')document.body.dataset.view='desk';$('.workspace').dataset.mobilePanel=panel;document.querySelectorAll('[data-panel]').forEach(b=>{b.classList.toggle('active',b.dataset.panel===panel);b.setAttribute('aria-pressed',String(b.dataset.panel===panel));});$('#notebook').classList.remove('show-notebook');if(matchMedia('(max-width:650px)').matches)window.scrollTo({top:0,behavior:'instant'});}
document.querySelectorAll('[data-panel]').forEach(b=>b.addEventListener('click',()=>setPanel(b.dataset.panel)));
$('#notes-toggle').addEventListener('click',()=>{if(matchMedia('(max-width:650px)').matches)setPanel('notebook');else $('#notebook').classList.toggle('show-notebook');});
$('#notes-close').addEventListener('click',()=>$('#notebook').classList.remove('show-notebook'));
function noteArticle(clue,i){const item=node('article','','clue-note');const heading=node('div','','clue-note-heading');heading.append(node('span',String(i+1).padStart(2,'0')),node('h3',clue.title));item.append(heading,node('q',clue.quotes.join(' · ')),node('p',clue.why));return item;}
function renderNotes(all){const container=$('#notes-body');container.replaceChildren();const clues=all||[...pinned.values()];$('#clue-count').textContent=`${pinned.size} clue${pinned.size===1?'':'s'} pinned`;$('#notes-count').textContent=clues.length;if(!clues.length){if(revealed){container.append(node('p','No obvious warning patterns were found. That does not establish that the message is genuine. Verify the sender and context independently.','notes-intro'));}else{const intro=node('p','','notes-intro');intro.append(node('b','Your gut has entered the chat.'),document.createTextNode(' Tap underlined phrases in the message to pin your evidence here.'));const empty=node('div','','notes-empty');empty.append(node('span','⌕','doodle-search'),node('p','No clues pinned. Yet.\nGood detectives look twice.'));container.append(intro,empty);}}else{container.append(node('p',revealed?'THE EVIDENCE, UNPACKED':`${clues.length} OBSERVATION${clues.length===1?'':'S'} PINNED`,'notes-summary'));clues.forEach((clue,i)=>container.append(noteArticle(clue,i)));}}
function makeEvidence(part,index){const b=node('button',part.text,'evidence-word');b.dataset.clue=String(index);b.setAttribute('aria-pressed',String(pinned.has(index)));b.classList.toggle('selected',pinned.has(index));b.classList.toggle('revealed',revealed);b.setAttribute('aria-label',`Investigate: ${part.text}`);b.addEventListener('click',()=>{if(revealed)return;if(pinned.has(index))pinned.delete(index);else pinned.set(index,part.clue);b.classList.toggle('selected',pinned.has(index));b.setAttribute('aria-pressed',String(pinned.has(index)));renderNotes();});return b;}
function renderMessage(){const container=$('#message-content');container.replaceChildren();container.classList.toggle('own-case-message',mode==='lab');if(mode==='lab'){highlightCustom(customText,analyze(customText).findings);return;}cases[current].parts.forEach((part,i)=>container.append(typeof part==='string'?document.createTextNode(part):makeEvidence(part,i)));}
function resetDesk(){$('.desk-disclaimer').textContent='A second opinion, never proof. This tool cannot verify a sender or certify a message as safe.';pinned=new Map();revealed=false;$('#case-outcome').hidden=true;$('#case-outcome').replaceChildren();$('#next-case').hidden=true;$('#verdict-buttons').hidden=false;$('#desk').classList.remove('lab-mode');$('.desk-status').replaceChildren(node('span','● WORKING LOCALLY'),node('span','NO UPLOADED OR SAVED MESSAGES'),node('span','KL / 2026'));$('#case-status').classList.remove('closed');$('#case-status').replaceChildren(node('i'),document.createTextNode(' OPEN CASE'));$('#document-hint').textContent='↑ Tap anything that makes you suspicious.';}
function openCase(index){hideChecker();deadline=timed?Date.now()+20000:0;frozenRemaining=20000;current=index;mode='training';resetDesk();const c=cases[index];$('#case-category').textContent=c.category;$('#case-title').textContent=c.title;$('#crumb').textContent='Case files';$('#crumb-id').textContent=String(index+1).padStart(3,'0');$('#channel-label').textContent=c.channel;$('#sender-name').textContent=c.sender;$('#sender-detail').textContent=c.detail;$('#sender-avatar').textContent=c.avatar;renderMessage();renderNotes();updateList();setPanel('desk');if(answers.has(index))showOutcome(answers.get(index),false);}
function caseClues(){return cases[current].parts.filter(p=>typeof p!=='string').map(p=>p.clue);}
function showOutcome(correct,record=true){revealed=true;if(record){frozenRemaining=Math.max(0,deadline-Date.now());answers.set(current,correct);const earned=scoreAnswer(correct,timed?Math.max(0,deadline-Date.now()):0);awarded.set(current,earned);points+=earned;updateHUD();}$('#verdict-buttons').hidden=true;$('#case-status').classList.add('closed');$('#case-status').replaceChildren(node('i'),document.createTextNode(' FILE REVIEWED'));$('#document-hint').textContent='Evidence unpacked. Open your case notes for the details.';renderMessage();renderNotes(caseClues());const outcome=$('#case-outcome');outcome.replaceChildren(node('span',correct?'INSTINCTS: SHARP':'LESSON: LEARNED','outcome-stamp'),node('h3',correct?'You’re getting hard to fool.':'One for your detective notebook.'),node('p',cases[current].explanation));outcome.hidden=false;$('#next-case').hidden=false;$('#next-case').replaceChildren(document.createTextNode(answers.size===cases.length?'All files reviewed · Start again':'Open the next case'),node('span',answers.size===cases.length?'↺':'→'));updateList();if(correct&&record)celebrate();}
document.querySelectorAll('[data-verdict]').forEach(b=>b.addEventListener('click',()=>{if(revealed||mode!=='training')return;showOutcome((b.dataset.verdict==='true')===cases[current].suspicious);}));
$('#next-case').addEventListener('click',()=>{if(answers.size===cases.length){newRound();}else{let next=cases.findIndex((_,i)=>i>current&&!answers.has(i));if(next<0)next=cases.findIndex((_,i)=>!answers.has(i));openCase(next);}});
$('#reset').addEventListener('click',()=>newRound());
const dialogs=['guide','help','about','privacy','faq','live'];for(const id of dialogs){const button=$('#'+(id==='compose'?'compose':id+'-open'));button.addEventListener('click',()=>$('#'+id+'-dialog').showModal());}
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
$('#custom-message').addEventListener('input',()=>{$('#char-count').textContent=`${$('#custom-message').value.length} / 2000`;$('#custom-message').setCustomValidity('');});
function highlightCustom(text,findings){const root=$('#message-content');root.replaceChildren();const ranges=[];findings.forEach(f=>f.quotes.forEach(quote=>{let from=0;const lower=text.toLowerCase(),needle=quote.toLowerCase();while(needle&&from<text.length){const start=lower.indexOf(needle,from);if(start<0)break;ranges.push({start,end:start+quote.length,clue:f});from=start+quote.length;}}));ranges.sort((a,b)=>a.start-b.start||b.end-a.end);let at=0;for(const range of ranges){if(range.start<at)continue;root.append(document.createTextNode(text.slice(at,range.start)));const mark=node('mark',text.slice(range.start,range.end),'evidence-word revealed');root.append(mark);at=range.end;}root.append(document.createTextNode(text.slice(at)));}
function runLocalCheck(event){aiGeneration++;event.preventDefault();const input=$('#custom-message');if(!input.value.trim()){input.setCustomValidity('Add a message to investigate.');input.reportValidity();return;}if(liveRoom)leaveRoom();customText=input.value;mode='lab';resetDesk();mode='lab';revealed=true;$('#desk').classList.add('lab-mode');showAnalysis();$('#case-category').textContent='PRIVATE INVESTIGATION / YOUR MESSAGE';$('#case-title').textContent='Let’s read between the lines.';$('#crumb').textContent='Message lab';$('#crumb-id').textContent='LOCAL';$('#channel-label').textContent='YOUR MESSAGE';$('#sender-name').textContent='Unverified sender';$('#sender-detail').textContent='Pasted by you · Processed on this device';$('#sender-avatar').textContent='⌕';$('#document-hint').textContent='Highlighted phrases matched common warning patterns.';const result=analyze(customText);renderMessage();renderNotes(result.findings);$('#case-status').replaceChildren(node('i'),document.createTextNode(' PATTERN CHECK'));$('#verdict-buttons').hidden=true;const out=$('#case-outcome');out.replaceChildren(node('span',`${result.findings.length} WARNING PATTERN${result.findings.length===1?'':'S'}`,'outcome-stamp'),node('h3',result.level),node('p',result.findings.length?'Pause before you act. Do not reply, pay, share codes, or follow message links. Check through the company’s known app or website; for personal messages, use a contact you already know.':'We did not find a matching warning pattern. This is not verification. Check the sender and context independently before sharing anything or acting.'));const again=node('button','Check another message ↗','scan-again');again.addEventListener('click',()=>showChecker());out.append(again);out.hidden=false;updateList();setPanel('desk');}

function celebrate(){if(matchMedia('(prefers-reduced-motion:reduce)').matches)return;const party=node('div','','confetti');party.setAttribute('aria-hidden','true');for(let i=0;i<22;i++){const bit=node('i');bit.style.setProperty('--x',`${Math.random()*100}vw`);bit.style.setProperty('--r',`${Math.random()*720}deg`);bit.style.setProperty('--delay',`${Math.random()*.3}s`);bit.style.background=['#c94627','#d7ef74','#b6a1c8','#f3d78f'][i%4];party.append(bit);}document.body.append(party);setTimeout(()=>party.remove(),2000);}
openCase(0);

function newRound(){hideChecker();aiGeneration++;if(liveRoom){leaveRoom();}cases=drawRound(usedCases);answers.clear();awarded.clear();points=0;openCase(0);updateHUD();}
function updateHUD(){const hud=$('#round-hud');hud.hidden=mode==='lab';$('#points-value').textContent=String(points);$('#mode-label').textContent=timed?'BEAT THE CLOCK':'PRACTICE ROUND';const remaining=deadline?Math.max(0,Math.ceil((revealed?frozenRemaining:deadline-Date.now())/1000)):0;$('#timer-value').textContent=timed?`${remaining}s`:'∞';hud.classList.toggle('timer-urgent',timed&&remaining<=5&&!revealed);$('#timer-caption').textContent=timed?'LEFT THIS CASE':'TAKE YOUR TIME';}
$('#sprint-open').addEventListener('click',()=>$('#sprint-dialog').showModal());
$('#sprint-start').addEventListener('click',()=>{timed=true;$('#sprint-dialog').close();newRound();});
$('#practice-mode').addEventListener('click',()=>{timed=false;newRound();});
setInterval(()=>{if(liveRoom)return;if(timed&&mode==='training'&&!revealed&&deadline&&Date.now()>=deadline){showOutcome(false);$('#case-outcome h3').textContent='Time’s up. A clue for next time.';}updateHUD();},250);
updateHUD();

const ROOM_API='https://phish-bureau-live.narutoxkillua.chatgpt.site';
let lastLiveView='',lastLiveAnswer='',lastLiveBoard='',answerBusy=false;
async function roomRequest(path,body,credential){const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),path==='/analyze'?30000:10000);try{const response=await fetch(ROOM_API+path,{method:'POST',headers:{'Content-Type':'application/json',...(credential?{Authorization:'Bearer '+credential}:{})},body:JSON.stringify(body),signal:controller.signal});let data;try{data=await response.json();}catch{throw Error('Room service is not available. Solo modes still work.');}if(!response.ok)throw Error(data.error||'The room request failed.');return data;}catch(error){if(error.name==='AbortError')throw Error('Room connection timed out. Try again.');throw error;}finally{clearTimeout(timeout);}}
function persistRoom(){try{if(liveRoom)sessionStorage.setItem('phish-room',JSON.stringify(liveRoom));else sessionStorage.removeItem('phish-room');}catch{}}
function leaveRoom(){if(pollHandle)clearInterval(pollHandle);pollHandle=null;liveRoom=null;liveState=null;liveBusy=false;lastLiveView='';lastLiveAnswer='';lastLiveBoard='';persistRoom();$('#desk').classList.remove('live-mode');$('.notebook-heading h2').textContent='The little things matter.';$('#live-status-error')?.remove();}
function startPolling(){if(pollHandle)clearInterval(pollHandle);pollRoom();pollHandle=setInterval(pollRoom,2000);}
async function pollRoom(){if(!liveRoom||liveBusy||answerBusy)return;liveBusy=true;const activeRoom=liveRoom;try{const state=await roomRequest('/state',{code:activeRoom.code},activeRoom.playerToken);if(liveRoom!==activeRoom||answerBusy)return;liveOffset=state.serverNow-Date.now();liveState=state;renderLive(state);$('#live-status-error')?.remove();}catch(error){if(liveRoom!==activeRoom)return;let notice=$('#live-status-error');if(!notice){notice=node('p','','live-error');notice.id='live-status-error';$('#notes-body').prepend(notice);}notice.textContent=error.message+' Reconnecting…';}finally{liveBusy=false;}}
function renderLeaderboard(state){const signature=JSON.stringify([state.status,state.players]);if(signature===lastLiveBoard)return;lastLiveBoard=signature;const root=$('#notes-body');root.replaceChildren();root.append(node('p',state.status==='finished'?'FINAL STANDINGS':'LIVE STANDINGS · UPDATES EVERY 2s','notes-summary'));const table=node('table','','leaderboard');const caption=node('caption','Players ranked by points, then correct calls.');caption.className='sr-only';table.append(caption);const head=node('thead'),tr=node('tr');['#','DETECTIVE','PTS'].forEach(t=>tr.append(node('th',t)));head.append(tr);table.append(head);const body=node('tbody');let rank=0,previous=null;state.players.forEach((p,i)=>{if(!previous||p.score!==previous.score||p.correct!==previous.correct)rank=i+1;previous=p;const row=node('tr','',''+(p.id===state.playerId?'is-me':''));row.append(node('td',String(rank)),node('td',p.name+(p.id===state.playerId?' (you)':'')),node('td',String(p.score)));body.append(row);});table.append(body);root.append(table,node('p','100 per correct call + up to 40 for speed. Missed cases score zero. Tied scores share a rank.','room-session-label'));if(liveRoom.hostToken&&state.status==='lobby'){const start=node('button','Start for everyone ↗','flag-button');start.style.marginTop='20px';start.addEventListener('click',async()=>{start.disabled=true;try{await roomRequest('/start',{code:liveRoom.code},liveRoom.hostToken);await pollRoom();}catch(e){start.disabled=false;root.append(node('p',e.message,'live-error'));}});root.append(start);}const controls=node('div','','room-controls');const copy=node('button','Copy invite ↗');copy.addEventListener('click',async()=>{const url=new URL(location.href);url.searchParams.set('room',liveRoom.code);try{await navigator.clipboard.writeText(url.toString());copy.textContent='Invite copied ✓';}catch{copy.textContent='Room code: '+liveRoom.code;}});const exit=node('button','Leave room');exit.addEventListener('click',()=>{leaveRoom();timed=false;newRound();});controls.append(copy,exit);root.append(controls);}
function renderLive(state){hideChecker();$('.desk-status').replaceChildren(node('span','● LIVE ROOM CONNECTED'),node('span','NICKNAMES + SCORES SHARED'),node('span','KL / 2026'));mode='live';timed=false;$('#desk').classList.add('live-mode');$('#round-hud').hidden=false;$('.notebook-heading h2').textContent=state.status==='finished'?'The final word.':'The leaderboard.';$('#crumb').textContent='Live room';$('#crumb-id').textContent=state.code;$('#mode-label').textContent='ROOM '+state.code;const me=state.players.find(p=>p.id===state.playerId);$('#points-value').textContent=String(me?.score||0);$('#case-counter').textContent=`${state.players.length} / 24 PLAYERS`;$('#detective-rank').textContent=state.status==='finished'?'Round complete':'Live investigation';$('#detective-score').textContent=state.code+' · '+state.players.length+' players';$('#notes-count').textContent=state.players.length;
 list.replaceChildren();state.players.forEach((p,i)=>{const row=node('div','','case-row'+(p.id===state.playerId?' active':''));const text=node('span');text.append(node('span',p.name,'case-row-title'),node('span',`${p.correct} correct · ${p.answered} answered`,'case-row-subtitle'));row.append(node('span',String(i+1).padStart(2,'0'),'case-num'),text,node('span',String(p.score),'case-row-tag'));list.append(row);});renderLeaderboard(state);
 const view=state.status+':'+state.index;if(view!==lastLiveView){lastLiveView=view;lastLiveAnswer='';resetDesk();$('#desk').classList.add('live-mode');$('#round-hud').hidden=false;$('#next-case').hidden=true;$('#case-category').textContent='LIVE ROOM / '+state.code;$('#case-status').replaceChildren(node('i'),document.createTextNode(state.status==='playing'?' LIVE CASE':state.status==='finished'?' FINISHED':' WAITING'));$('#document-hint').textContent='Same case. Same clock. Trust your judgment.';if(state.question){cases=[state.question];current=0;$('#case-title').textContent=state.question.title;$('#sender-name').textContent=state.question.sender;$('#sender-detail').textContent=state.question.detail;$('#sender-avatar').textContent=state.question.avatar;$('#channel-label').textContent=state.question.channel;$('#message-content').replaceChildren(document.createTextNode(state.question.parts.join('')));$('#verdict-buttons').hidden=false;}else{$('#verdict-buttons').hidden=true;$('#case-title').textContent=state.status==='finished'?'The results are in.':'Your rivals are assembling.';$('#sender-name').textContent='The Phish Bureau';$('#sender-detail').textContent='Shared investigation room';$('#sender-avatar').textContent='✳';$('#channel-label').textContent='COMPETITION DESK';const text=state.status==='finished'?'Round complete. Open the notebook for the final leaderboard. Create a new room for a fresh set of cases.':state.status==='countdown'?'Get ready. Eight messages. Twenty seconds each. The first case opens together.':'Room '+state.code+' is open. Share the code with your friends. Everyone must join before the host starts.';$('#message-content').replaceChildren(node('div',text,'lobby-message'));if(state.status==='lobby')$('#message-content').append(node('span',state.code,'room-code-display'));}setPanel('desk');$('.desk-status').replaceChildren(node('span','● LIVE ROOM CONNECTED'),node('span','NICKNAMES + SCORES SHARED'),node('span','KL / 2026'));}
 if(state.answer){const key=state.index+':'+state.answer.points;if(key!==lastLiveAnswer){lastLiveAnswer=key;revealed=true;$('#verdict-buttons').hidden=true;const out=$('#case-outcome');out.replaceChildren(node('span',`+${state.answer.points} POINTS`,'outcome-stamp'),node('h3',state.answer.correct?'Good call. Stay sharp.':'A lesson for the next case.'),node('p',state.answer.explanation));out.hidden=false;}}
 updateLiveClock();}
function updateLiveClock(){if(!liveRoom||!liveState)return;const state=liveState,now=Date.now()+liveOffset;const remaining=state.status==='playing'?Math.max(0,state.deadline-now):state.status==='countdown'?Math.max(0,state.startAt-now):0;$('#timer-value').textContent=state.status==='lobby'?'—':state.status==='finished'?'✓':Math.ceil(remaining/1000)+'s';$('#timer-caption').textContent=state.status==='lobby'?'WAITING':state.status==='countdown'?'STARTING IN':state.status==='finished'?'ROUND OVER':'LEFT THIS CASE';$('#round-hud').classList.toggle('timer-urgent',state.status==='playing'&&remaining<=5000&&!state.answer);if(state.status==='playing'&&remaining<=0){$('#verdict-buttons').hidden=true;$('#document-hint').textContent='Case closed. Synchronizing the next case…';}}
setInterval(updateLiveClock,200);
document.querySelectorAll('[data-verdict]').forEach(b=>b.addEventListener('click',async()=>{if(!liveRoom||!liveState||liveState.status!=='playing'||liveState.answer||answerBusy)return;answerBusy=true;const room=liveRoom;const index=liveState.index;document.querySelectorAll('[data-verdict]').forEach(x=>x.disabled=true);try{const result=await roomRequest('/answer',{code:room.code,index,choice:b.dataset.verdict==='true'},room.playerToken);if(liveRoom===room){liveState.answer=result;renderLive(liveState);if(result.correct)celebrate();await pollRoom();}}catch(error){if(liveRoom===room){$('#case-outcome').replaceChildren(node('p',error.message,'live-error'));$('#case-outcome').hidden=false;await pollRoom();}}finally{answerBusy=false;document.querySelectorAll('[data-verdict]').forEach(x=>x.disabled=false);}}));
$('#room-form').addEventListener('submit',async event=>{event.preventDefault();const name=$('#player-name').value.trim(),code=$('#room-code-field').hidden?'':$('#room-code').value.toUpperCase().replace(/[\s-]/g,'');if(!$('#room-code-field').hidden&&!/^[A-Z2-9]{6}$/.test(code)){$('#room-error').textContent='Paste the six-character code shared by your host. Codes do not contain 0 or 1. To host your own, choose Create a new room.';return;}const connect=$('#room-connect'),create=$('#room-create');connect.disabled=create.disabled=true;$('#room-error').textContent='Connecting…';try{const result=await roomRequest(code?'/join':'/rooms',{name,...(code?{code}:{used:[...usedCases]})});leaveRoom();liveRoom=result;(result.caseIds||[]).forEach(id=>usedCases.add(id));persistRoom();lastLiveView='';$('#live-dialog').close();$('#room-error').textContent='';startPolling();}catch(error){$('#room-error').textContent=error.message;}finally{connect.disabled=create.disabled=false;}});
// A room invite fills the join form; it does not join or send a name automatically.
function setRoomEntry(join){$('#room-code-field').hidden=!join;$('#room-code').disabled=!join;$('#room-code').required=join;$('#room-create').hidden=join;$('#room-connect').hidden=!join;$('#room-host-tab').setAttribute('aria-pressed',String(!join));$('#room-join-tab').setAttribute('aria-pressed',String(join));$('#room-entry-hint').textContent=join?'Ask your host for the code, then join before the round starts.':'We’ll generate a code for you to share after you create the room.';$('#room-error').textContent='';}
$('#room-host-tab').addEventListener('click',()=>setRoomEntry(false));$('#room-join-tab').addEventListener('click',()=>setRoomEntry(true));
const invite=new URLSearchParams(location.search).get('room');if(invite&&/^[A-Z2-9]{6}$/i.test(invite)){setRoomEntry(true);$('#room-code').value=invite.toUpperCase();$('#live-dialog').showModal();}
try{const saved=JSON.parse(sessionStorage.getItem('phish-room')||'null');if(saved&&saved.expiresAt>Date.now()&&saved.playerToken&&saved.code&&(!invite||saved.code===invite.toUpperCase())){liveRoom=saved;$('#live-dialog').close();startPolling();}}catch{}

if(['#privacy','#faq'].includes(location.hash))$('#'+location.hash.slice(1)+'-dialog').showModal();

$('#compose-form').addEventListener('submit',async event=>{event.preventDefault();$('#ai-form-error').textContent='';if(event.submitter?.dataset.check==='local'){runLocalCheck(event);return;}const input=$('#custom-message');const text=input.value.trim();if(!text)return;if(!$('#ai-consent').checked){$('#ai-form-error').textContent='Select the checkbox to send this text to Google, or choose the local check.';return;}if(liveRoom)leaveRoom();if(gmailSelectedText){$('#ai-form-error').textContent='Gmail-selected messages are checked locally. They cannot be sent to this free AI endpoint.';return;}const request=++aiGeneration;customText=text;mode='lab';resetDesk();mode='lab';revealed=true;$('#desk').classList.add('lab-mode');showAnalysis();$('#case-category').textContent='GEMMA 4 / AI MESSAGE REVIEW';$('#case-title').textContent='A second opinion is on the case.';$('#crumb').textContent='AI message lab';$('#crumb-id').textContent='GEMMA 4';$('#sender-name').textContent='Your submitted message';$('#sender-detail').textContent='Sent to Google for AI review · Not saved by this app';$('#sender-avatar').textContent='✳';$('#channel-label').textContent='MESSAGE EVIDENCE';$('#message-content').replaceChildren(document.createTextNode(text));$('#document-hint').textContent='AI reviews text only. Links are never opened.';$('#verdict-buttons').hidden=true;$('#next-case').hidden=true;$('#notes-body').replaceChildren(node('p','Gemma 4 is examining the message…','notes-intro'));$('#case-outcome').hidden=false;$('#case-outcome').replaceChildren(node('h3','Gemma 4 is reviewing…'),node('p','Looking for warning signs, context, and a safe next step.'));$('.desk-status').replaceChildren(node('span','● GEMMA 4 AI REVIEW'),node('span','MESSAGE SENT TO GOOGLE'));setPanel('desk');try{const result=await roomRequest('/analyze',{message:text,consent:true});if(request!==aiGeneration||mode!=='lab'||customText!==text)return;const labels={likely_scam:'Likely scam — pause before acting',uncertain:'Uncertain — verify independently',no_obvious_signs:'No obvious scam signs — still verify'};const out=$('#case-outcome');out.replaceChildren(node('span','GEMMA 4 · AI ASSESSMENT','outcome-stamp'),node('h3',labels[result.verdict]||'Review the evidence'),node('p',result.summary));out.append(node('p','AI can be wrong. This does not verify identity, links, or safety.','limit'));$('#notes-body').replaceChildren(node('p','GEMMA 4’S OBSERVATIONS','notes-summary'));result.clues.forEach((c,i)=>$('#notes-body').append(noteArticle({title:'Clue '+(i+1),quotes:[c.quote],why:c.reason},i)));const steps=node('div','','ai-next-steps');steps.append(node('h3','Your safer next move'));result.nextSteps.forEach(s=>steps.append(node('p','→ '+s)));$('#notes-body').append(steps);$('#notes-count').textContent=result.clues.length;$('#case-status').replaceChildren(node('i'),document.createTextNode(' AI REVIEWED'));}catch(error){if(request!==aiGeneration||mode!=='lab')return;$('#case-outcome').replaceChildren(node('h3','AI review unavailable'),node('p',error.message));const retry=node('button','Try again or check locally ↗','scan-again');retry.addEventListener('click',()=>showChecker());$('#case-outcome').append(retry);$('#notes-body').replaceChildren(node('p','No AI assessment was returned. You can still run the separate local pattern check.','notes-intro'));}});
$('#email-file').addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;const note=$('#import-note');try{if(file.size>65536)throw Error('Choose a file smaller than 64 KB.');if(!/\.(eml|txt)$/i.test(file.name))throw Error('Choose an .eml or .txt file.');const raw=await file.text();const {importEmail}=await import('./email-import.mjs?v=20261114-10');const extracted=/\.eml$/i.test(file.name)?importEmail(raw):raw;$('#custom-message').value=extracted.slice(0,2000);$('#custom-message').dispatchEvent(new Event('input'));$('#ai-consent').checked=false;note.textContent=extracted.length>2000?'Imported the first 2000 characters. Review and remove private details before sending.':'Imported locally. Review the text and remove private details before sending.';}catch(error){note.textContent=error.message;}event.target.value='';});

function syncNavigation(){const active=document.body.dataset.view==='home'||document.body.dataset.view==='analysis'?'home-open':liveRoom?'live-open':timed?'sprint-open':'practice-mode';document.querySelectorAll('.play-modes button').forEach(b=>{b.classList.toggle('active',b.id===active);if(b.id===active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});}
function showChecker(){aiGeneration++;if(liveRoom)leaveRoom();timed=false;deadline=0;document.body.dataset.view='home';syncNavigation();window.scrollTo({top:0,behavior:'instant'});$('#custom-message').focus({preventScroll:true});}
function hideChecker(){document.body.dataset.view='desk';syncNavigation();}
function showAnalysis(){document.body.dataset.view='analysis';syncNavigation();}
$('#home-form-slot').append($('#compose-form'));
$('#home-open').addEventListener('click',showChecker);
$('#play-link').addEventListener('click',()=>{hideChecker();timed=false;newRound();});
$('#custom-message').addEventListener('input',()=>{if(gmailSelectedText){$('#ai-consent').checked=false;$('#ai-form-error').textContent='This message came from Gmail and will use local checks.';}});
if(!liveRoom&&location.hash!=='#play')document.body.dataset.view='home';syncNavigation();
$('#compose').addEventListener('click',showChecker);
$('.brand').addEventListener('click',event=>{event.preventDefault();showChecker();});

let gmailReader=null,gmailTokenClient=null,gmailModule=null;
$('#gmail-open').addEventListener('click',async()=>{$('#gmail-dialog').showModal();const connect=$('#gmail-connect');connect.disabled=true;$('#gmail-status').textContent='Preparing Gmail connection…';try{gmailModule=await import('./gmail.mjs?v=20261114-10');const {GMAIL_CLIENT_ID,GMAIL_RELEASE}=await import('./gmail-config.mjs?v=20261114-10');if(!GMAIL_CLIENT_ID){$('#gmail-status').textContent='Gmail connection is being configured. Paste a message or import an .eml file in the meantime.';return;}await gmailModule.loadGoogleIdentity();gmailReader??=new gmailModule.GmailReader();gmailTokenClient??=google.accounts.oauth2.initTokenClient({client_id:GMAIL_CLIENT_ID,scope:gmailModule.GMAIL_SCOPE,include_granted_scopes:false,callback:async result=>{try{if(!google.accounts.oauth2.hasGrantedAllScopes(result,gmailModule.GMAIL_SCOPE))throw Error('Read-only Gmail permission was not granted.');gmailReader.setToken(result);connect.hidden=true;$('#gmail-picker').hidden=false;await showGmailList();}catch(error){$('#gmail-status').textContent=error.message;connect.disabled=false;}},error_callback:()=>{$('#gmail-status').textContent='Google sign-in was closed or blocked. Choose Connect Gmail to try again.';connect.disabled=false;}});connect.disabled=false;$('#gmail-status').textContent=GMAIL_RELEASE==='testing'?'Gmail beta: currently available to approved Google test accounts.':'';}catch(error){$('#gmail-status').textContent=error.message;}});
$('#gmail-connect').addEventListener('click',()=>{if(!gmailTokenClient)return;$('#gmail-status').textContent='Continue in the Google permission window.';gmailTokenClient.requestAccessToken({prompt:'consent'});});
async function showGmailList(){const root=$('#gmail-messages');root.replaceChildren();$('#gmail-status').textContent='Loading up to 12 email headers from Gmail…';try{const {rows,more}=await gmailReader.list($('#gmail-query').value);for(const message of rows){const b=node('button','','gmail-email-row');b.type='button';b.append(node('b',gmailModule.headerValue(message,'Subject')||'(No subject)'),node('small',gmailModule.headerValue(message,'From')),node('small',gmailModule.headerValue(message,'Date')));b.addEventListener('click',async()=>{b.disabled=true;$('#gmail-status').textContent='Reading your selected message…';try{const selected=await gmailReader.read(message.id,message.sizeEstimate);const imported=gmailModule.selectedEmailText(selected);gmailSelectedText=true;$('#custom-message').value=imported.text;$('#custom-message').dispatchEvent(new Event('input'));$('#ai-consent').checked=false;$('#gmail-dialog').close();showChecker();$('#import-note').textContent=imported.previewOnly?'Gmail preview imported (no plain-text body). Local checks only.':'Selected Gmail email imported. Local checks only; it will not be sent to the free AI service.';$('#ai-form-error').textContent='Gmail-selected email: choose “Check patterns locally”.';}catch(error){$('#gmail-status').textContent=error.message;b.disabled=false;}});root.append(b);}$('#gmail-status').textContent=rows.length?(more?`Showing ${rows.length} matching emails. Refine your search or use the mailbox scan for more.`:'Choose one email to import its text.'):'No matching emails. Try a different search.';}catch(error){$('#gmail-status').textContent=error.message;}}
$('#gmail-search').addEventListener('submit',event=>{event.preventDefault();showGmailList();});
$('#gmail-disconnect').addEventListener('click',()=>{clearGmailScan();localGemma?.terminate();$('#gemma-device-status').textContent='AI unloaded. Downloaded model weights remain cached for reuse.';refreshGmailAI();const accessToken=gmailReader?.accessToken;gmailReader?.clear();if(accessToken&&globalThis.google?.accounts?.oauth2)google.accounts.oauth2.revoke(accessToken,()=>{});$('#gmail-messages').replaceChildren();$('#gmail-query').value='';$('#gmail-picker').hidden=true;$('#gmail-connect').hidden=false;$('#gmail-status').textContent='Disconnected. Gmail access and imported text cleared from this tab.';if(gmailSelectedText){$('#message-content').replaceChildren();$('#notes-body').replaceChildren();$('#case-outcome').replaceChildren();$('#custom-message').value='';gmailSelectedText=false;$('#custom-message').dispatchEvent(new Event('input'));$('#import-note').textContent='Import reads the file locally.';$('#ai-form-error').textContent='';}});

$('#clear-message').addEventListener('click',()=>{gmailSelectedText=false;$('#custom-message').value='';$('#ai-consent').checked=false;$('#custom-message').dispatchEvent(new Event('input'));$('#ai-form-error').textContent='';$('#import-note').textContent='Import reads the file locally. Nothing is sent until you choose AI review.';});

let gmailScanController=null,gmailScanGeneration=0;
function stopGmailScan(){for(const id of ['gmail-scan-engine','gmail-ai-limit','gmail-ai-consent'])$('#'+id).disabled=false;gmailScanGeneration++;gmailScanController?.abort();gmailScanController=null;$('#gmail-scan-start').disabled=false;$('#gmail-scan-stop').hidden=true;$('#gmail-scan-scope').disabled=false;$('#gmail-scan-spam').disabled=false;$('#gmail-search button').disabled=false;refreshGmailAI();}
function clearGmailScan(){stopGmailScan();$('#gmail-scan-results').replaceChildren();$('#gmail-scan-progress').textContent='Scan results cleared from this tab.';}
$('#gmail-scan-stop').addEventListener('click',()=>{stopGmailScan();$('#gmail-scan-progress').textContent+=' Stopped. Results are partial; start a new scan to check again.';});
$('#gmail-dialog').addEventListener('close',()=>{if(gmailScanController){stopGmailScan();$('#gmail-scan-progress').textContent+=' Stopped when the picker closed. Results are partial.';}});
$('#gmail-scan-start').addEventListener('click',async()=>{
 if(!gmailReader?.accessToken){$('#gmail-scan-progress').textContent='Connect Gmail first.';return;}
 const useGemma=$('#gmail-scan-engine').value==='gemma';if(useGemma&&(!gmailAiReady||!$('#gmail-ai-consent').checked)){$('#gmail-scan-progress').textContent='Prepare Gemma on this device, then select the on-device AI checkbox.';return;}
 clearGmailScan();for(const id of ['gmail-scan-engine','gmail-ai-limit','gmail-ai-consent'])$('#'+id).disabled=true;const generation=++gmailScanGeneration,controller=new AbortController();gmailScanController=controller;
 const root=$('#gmail-scan-results'),progress=$('#gmail-scan-progress');let retained=0,lastStats={checked:0,flagged:0,limited:0};
 $('#gmail-scan-start').disabled=true;$('#gmail-scan-stop').hidden=false;$('#gmail-scan-scope').disabled=true;$('#gmail-scan-spam').disabled=true;$('#gmail-search button').disabled=true;
 const scope=$('#gmail-scan-scope').value;const query=scope==='recent'?'newer_than:30d':scope==='inbox'?'in:inbox':scope==='search'?$('#gmail-query').value.trim():'';
 if(scope==='search'&&!query){stopGmailScan();progress.textContent='Enter a Gmail search below before choosing Current Gmail search.';return;}
 progress.textContent=useGemma?'Starting on-device Gemma 4 review. Email text stays on this device…':'Starting local scan. Reading email headers and text from Gmail…';
 const summary=s=>`${useGemma?"GEMMA 4 · ":"LOCAL · "}${s.checked} emails checked · ${s.flagged} need review · ${s.limited} preview or shortened checks`;
 try{
 const {scanMailbox}=await import('./gmail-scan.mjs?v=20261114-10');
 const reviewEmail=useGemma?(text,signal)=>localGemma.review(text,signal):undefined;
 const stats=await scanMailbox(gmailReader,{query,reviewEmail,maxMessages:useGemma&&$('#gmail-ai-limit').value!=='all'?Number($('#gmail-ai-limit').value):Infinity,includeSpamTrash:$('#gmail-scan-spam').checked,signal:controller.signal,onProgress:s=>{if(generation!==gmailScanGeneration)return;lastStats=s;progress.textContent=summary(s)+(s.complete?' · Scan finished.':' · Scanning…');},onFinding:email=>{
 if(generation!==gmailScanGeneration||retained>=500)return;retained++;
 const item=node('article','','gmail-scan-result');item.dataset.score=String(email.score);item.append(node('span',email.ai?(email.ai.verdict==='likely_scam'?'GEMMA 4 · LIKELY SCAM':'GEMMA 4 · UNCERTAIN'):email.score>=6?'MULTIPLE WARNING SIGNS':'NEEDS A CLOSER LOOK','tiny-label'),node('h4',email.subject),node('p',email.from,'scan-sender'),node('small',email.date));if(email.ai)item.append(node('p','Gemma 4: '+email.ai.summary,'scan-ai-summary'));
 const clues=node('ul');email.findings.forEach(f=>clues.append(node('li',f.title)));item.append(clues);
 if(email.limited)item.append(node('p','Limited check: preview only or shortened content. Review the original email independently.','scan-limited'));
 const review=node('button',email.ai?'Read AI assessment →':'Review warning signs →');review.type='button';review.addEventListener('click',()=>{if(email.ai){let detail=item.querySelector('.scan-ai-detail');if(detail){detail.hidden=!detail.hidden;return;}detail=node('div','','scan-ai-detail');email.ai.nextSteps.forEach(step=>detail.append(node('p','→ '+step)));detail.append(node('p','AI can be wrong. Verify through a known, independent channel.'));item.append(detail);return;}gmailSelectedText=true;$('#custom-message').value=email.text;$('#custom-message').dispatchEvent(new Event('input'));$('#ai-consent').checked=false;$('#gmail-dialog').close();runLocalCheck({preventDefault(){}});$('#import-note').textContent='From your Gmail scan. Local checks only.';});item.append(review);
 const before=[...root.children].find(row=>Number(row.dataset.score)<email.score);root.insertBefore(item,before||null);
 }});
 if(generation!==gmailScanGeneration)return;
 progress.textContent=summary(stats)+(stats.capped?'. AI scan limit reached. Only the first '+stats.checked+' matching emails were reviewed; narrow the date range or search to check others.':'. Scan finished for the selected scope.')+(stats.flagged>500?' Showing the first 500 flagged emails; narrow the date range or search to review more.':'')+(!stats.flagged?(useGemma?' No emails were flagged by Gemma. This does not prove they are safe.':' No matching warning patterns found. This does not prove that the emails are safe.'):'');
 }catch(error){if(generation!==gmailScanGeneration)return;if(!gmailReader?.accessToken){$('#gmail-connect').hidden=false;$('#gmail-connect').disabled=false;}progress.textContent=summary(lastStats)+'. '+(error.name==='AbortError'?'Scan stopped. Results are partial.':error.message+' Scan incomplete; results are partial.');}
 finally{if(generation===gmailScanGeneration)stopGmailScan();}
});

let gmailAiReady=false,localGemma=null,gemmaLoadController=null;
function refreshGmailAI(){gmailAiReady=!!localGemma?.ready;$('#gemma-device-example').disabled=!gmailAiReady;$('#gmail-gemma-option').disabled=false;$('#gmail-ai-availability').textContent=gmailAiReady?'Gemma 4 is ready on this device. No cloud AI calls are used for Gmail.':'Prepare Gemma above to enable on-device AI review. Local pattern checks work immediately.';}
$('#gmail-open').addEventListener('click',refreshGmailAI);
$('#gmail-scan-engine').addEventListener('change',()=>{$('#gmail-ai-options').hidden=$('#gmail-scan-engine').value!=='gemma';$('#gmail-ai-consent').checked=false;});
$('#gemma-device-load').addEventListener('click',async()=>{
 const button=$('#gemma-device-load'),status=$('#gemma-device-status');button.disabled=true;$('#gemma-device-clear').disabled=true;$('#gemma-device-stop').hidden=false;gemmaLoadController=new AbortController();status.textContent='Checking this device and preparing the local runtime…';
 try{const {LocalGemma}=await import('./gemma-local.mjs?v=20261114-10');localGemma??=new LocalGemma();await localGemma.load({signal:gemmaLoadController.signal,onProgress:p=>{status.textContent=p.stage==='download'?`Downloading Gemma: ${(p.loaded/1e9).toFixed(2)} / ~${(p.total/1e9).toFixed(2)} GB. Email text is not uploaded.`:'Loading Gemma into your GPU. This may take a few minutes…';}});status.textContent='Gemma 4 E2B is ready on this device. No paid API calls. Connect Gmail and choose on-device AI review.';$('#gmail-scan-engine').value='gemma';$('#gmail-ai-options').hidden=false;$('#gmail-ai-consent').checked=false;}
 catch(error){localGemma?.terminate();status.textContent=error.message+' Local pattern checks are still available.';}
 finally{gemmaLoadController=null;button.disabled=false;$('#gemma-device-clear').disabled=false;$('#gemma-device-stop').hidden=true;refreshGmailAI();}
});
$('#gemma-device-stop').addEventListener('click',()=>gemmaLoadController?.abort());
$('#gemma-device-clear').addEventListener('click',async()=>{gemmaLoadController?.abort();clearGmailScan();try{if(localGemma)await localGemma.clear();else await caches.delete('phish-gemma4-model-v1');$('#gemma-device-status').textContent='Downloaded model removed from this browser. Email contents were never cached.';}catch(error){$('#gemma-device-status').textContent=error.message;}refreshGmailAI();});

$('#gemma-device-example').addEventListener('click',async()=>{const button=$('#gemma-device-example'),out=$('#gemma-device-example-result');button.disabled=true;out.textContent='Gemma is reviewing a fictional supplier email on this device…';const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),120000);try{const result=await localGemma.review('From: supplier-accounts@example.test\nSubject: Updated settlement instructions\nAs discussed, please use the replacement account for this month’s invoice. Our usual account is temporarily unavailable.',controller.signal);out.textContent='Fictional test · '+result.verdict.replaceAll('_',' ')+': '+result.summary;}catch(error){out.textContent=error.message;}finally{clearTimeout(timer);refreshGmailAI();}});
